    def test_calibration_rollbacks_preserve_live_binding_identity(self):
        class Binding:
            def __init__(self, value):
                self.value = value

            def get(self):
                return self.value

            def set(self, value):
                self.value = value

        for function_name in ("updateParams", "_apply_controller_calibration"):
            with self.subTest(function=function_name):
                binding = Binding(0)
                calibration = {"J1CalStatVal": binding}
                snapshots = []

                def restore(snapshot):
                    snapshots.append(dict(snapshot))
                    apply_calibration(snapshot, calibration)

                namespace = {
                    "CAL": calibration,
                    "_restore_controller_calibration": restore,
                }
                if function_name == "updateParams":
                    namespace.update({
                        "_prepare_update_parameters": (
                            lambda: ({"J1CalStatVal": 1}, "UPA1\n")
                        ),
                        "_apply_update_parameter_values": (
                            lambda values: (
                                binding.set(values["J1CalStatVal"])
                                or (_ for _ in ()).throw(
                                    RuntimeError("application failed")
                                )
                            )
                        ),
                    })
                    function = self.compile_function(
                        function_name,
                        namespace,
                    )
                    arguments = ()
                    keywords = {"transmit": False}
                else:
                    namespace.update({
                        "_apply_update_parameter_values": (
                            lambda values: binding.set(
                                values["J1CalStatVal"]
                            )
                        ),
                        "_apply_external_axis_values": (
                            lambda values: (_ for _ in ()).throw(
                                RuntimeError("application failed")
                            )
                        ),
                    })
                    function = self.compile_function(
                        function_name,
                        namespace,
                    )
                    arguments = ({"J1CalStatVal": 1}, {})
                    keywords = {}

                with self.assertRaisesRegex(
                    RuntimeError,
                    "application failed",
                ):
                    function(*arguments, **keywords)

                self.assertEqual(snapshots, [{"J1CalStatVal": 0}])
                self.assertIs(calibration["J1CalStatVal"], binding)
                self.assertEqual(binding.get(), 0)

    def test_update_parameter_write_invalidates_cached_home_reference(self):
        port = SimpleNamespace(is_open=True)
        for outcome in (True, RuntimeError("acknowledgement failed")):
            with self.subTest(outcome=outcome):
                invalidations = []

                def exchange_legacy(command, **options):
                    self.assertEqual(command, "UPA1\n")
                    self.assertFalse(options["read_line"])
                    self.assertEqual(options["expected_response"], b"Done")
                    self.assertEqual(options["response_timeout"], 1.0)
                    options["write_started_event"].set()
                    if isinstance(outcome, Exception):
                        raise outcome
                    return "Done"

                namespace = {
                    "RUN": {"ser": port},
                    "threading": threading,
                    "SERIAL_STARTUP_READ_TIMEOUT_SECONDS": 1.0,
                    "_exchange_legacy_main_command": exchange_legacy,
                    "_invalidate_bound_primary_home_reference": (
                        lambda serial_port: (
                            invalidations.append(serial_port)
                            or True
                        )
                    ),
                }
                exchange = self.compile_function(
                    "_exchange_controller_calibration_acknowledgement",
                    namespace,
                )

                if isinstance(outcome, Exception):
                    with self.assertRaisesRegex(
                        RuntimeError,
                        "acknowledgement failed",
                    ):
                        exchange("UPA1\n")
                else:
                    self.assertTrue(exchange("UPA1\n"))
                self.assertEqual(invalidations, [port])

