    def test_calibration_transmissions_require_exact_firmware_acknowledgement(self):
        port = SimpleNamespace(is_open=True)
        exchange_calls = []
        home_reference_invalidations = []

        def exchange_legacy(command, **options):
            exchange_calls.append((command, options))
            options["write_started_event"].set()
            return "Done"

        helper_namespace = {
            "RUN": {"ser": port},
            "threading": threading,
            "SERIAL_STARTUP_READ_TIMEOUT_SECONDS": 10,
            "_exchange_legacy_main_command": exchange_legacy,
            "_invalidate_bound_primary_home_reference": (
                lambda serial_port: (
                    home_reference_invalidations.append(serial_port)
                    or True
                )
            ),
        }
        exchange_acknowledgement = self.compile_function(
            "_exchange_controller_calibration_acknowledgement",
            helper_namespace,
        )

        self.assertTrue(exchange_acknowledgement("UPA1\n"))
        self.assertEqual(exchange_calls[0][0], "UPA1\n")
        self.assertEqual(
            {
                key: value
                for key, value in exchange_calls[0][1].items()
                if key != "write_started_event"
            },
            {
                "read_line": False,
                "expected_response": b"Done",
                "response_timeout": 10,
            },
        )
        self.assertTrue(
            exchange_calls[0][1]["write_started_event"].is_set()
        )
        self.assertEqual(len(exchange_calls), 1)
        self.assertEqual(home_reference_invalidations, [port])

        calls = []

        def exchange(command, write_started_event=None):
            calls.append((command, write_started_event))
            return True

        namespace = {
            "_exchange_controller_calibration_acknowledgement": exchange,
        }
        self.add_startup_command_dependencies(namespace)
        transmit_update = self.compile_function(
            "_transmit_update_parameters",
            namespace,
        )
        transmit_external = self.compile_function(
            "_transmit_external_axis_parameters",
            namespace,
        )

        self.assertTrue(transmit_update("UPA1\n"))
        self.assertTrue(transmit_external("CEA2\n"))
        self.assertEqual(
            calls,
            [("UPA1\n", None), ("CEA2\n", None)],
        )
        with self.assertRaisesRegex(
            MotionInputError,
            "must begin with 'CE'",
        ):
            transmit_external("UPA1\n")
        self.assertEqual(
            calls,
            [("UPA1\n", None), ("CEA2\n", None)],
        )

