    def test_failed_calibration_write_retains_dirty_state_and_retries(self):
        class Root:
            def __init__(self):
                self.jobs = []

            def after(self, delay, callback):
                job = f"job-{len(self.jobs) + 1}"
                self.jobs.append((job, delay, callback))
                return job

        class Logger:
            def __init__(self):
                self.errors = []
                self.exceptions = []

            def error(self, message):
                self.errors.append(message)

            def exception(self, message):
                self.exceptions.append(message)

        class Closing:
            @staticmethod
            def is_set():
                return False

        outcomes = [False, True]
        persisted_values = []
        root = Root()
        logger = Logger()
        namespace = {
            "_calibration_save_job": "initial-job",
            "_calibration_dirty": True,
            "_calibration_save_snapshot": {"J1AngCur": "0"},
            "save_calibration": (
                lambda calibration: (
                    persisted_values.append(dict(calibration))
                    or outcomes.pop(0)
                )
            ),
            "CAL": {"J1AngCur": "1"},
            "logger": logger,
            "application_closing": Closing(),
            "root": root,
            "CALIBRATION_SAVE_DEBOUNCE_MS": 250,
            "RuntimeError": RuntimeError,
            "tk": SimpleNamespace(TclError=RuntimeError),
        }
        write_pending = self.compile_function(
            "_write_pending_calibration",
            namespace,
        )

        self.assertFalse(write_pending())
        self.assertTrue(namespace["_calibration_dirty"])
        self.assertEqual(namespace["_calibration_save_job"], "job-1")
        self.assertEqual(
            namespace["_calibration_save_snapshot"],
            {"J1AngCur": "0"},
        )
        self.assertEqual(len(root.jobs), 1)
        self.assertEqual(logger.exceptions, [])

        self.assertTrue(write_pending())
        self.assertFalse(namespace["_calibration_dirty"])
        self.assertIsNone(namespace["_calibration_save_job"])
        self.assertIsNone(namespace["_calibration_save_snapshot"])
        self.assertEqual(
            persisted_values,
            [{"J1AngCur": "0"}, {"J1AngCur": "0"}],
        )

    def test_auxiliary_settle_reconciliation_preserves_live_job_ownership(self):
        safe_snapshot = self._valid_runtime_calibration()
        for mode in ("no-job", "cancelled", "cancel-failed", "ownership-changed"):
            with self.subTest(mode=mode):
                cancellations = []
                errors = []
                exceptions = []
                namespace = {
                    "_calibration_save_job": (
                        None
                        if mode == "no-job"
                        else "pending-job"
                    ),
                    "_calibration_dirty": True,
                    "_calibration_save_snapshot": {"J1AngCur": "0"},
                    "logger": SimpleNamespace(
                        error=lambda *args: errors.append(args),
                        exception=lambda *args: exceptions.append(args),
                    ),
                }

                def cancel(job):
                    cancellations.append(job)
                    if mode == "cancel-failed":
                        raise RuntimeError("cancel failed")
                    if mode == "ownership-changed":
                        namespace["_calibration_save_job"] = "replacement-job"

                namespace["root"] = SimpleNamespace(after_cancel=cancel)
                reconcile = self.compile_function(
                    "_reconcile_auxiliary_calibration_persistence_after_settle_failure",
                    namespace,
                )

                expected = mode in ("no-job", "cancelled")
                self.assertEqual(
                    reconcile(False, None, safe_snapshot),
                    expected,
                )
                self.assertEqual(
                    namespace["_calibration_dirty"],
                    not expected,
                )
                if expected:
                    self.assertIsNone(
                        namespace["_calibration_save_snapshot"]
                    )
                    self.assertIsNone(namespace["_calibration_save_job"])
                else:
                    self.assertEqual(
                        namespace["_calibration_save_snapshot"],
                        normalize_calibration_data(safe_snapshot),
                    )
                    self.assertEqual(
                        namespace["_calibration_save_job"],
                        (
                            "replacement-job"
                            if mode == "ownership-changed"
                            else "pending-job"
                        ),
                    )
                self.assertEqual(
                    cancellations,
                    [] if mode == "no-job" else ["pending-job"],
                )
                self.assertEqual(
                    len(exceptions),
                    1 if mode == "cancel-failed" else 0,
                )
                self.assertEqual(
                    len(errors),
                    1 if mode == "ownership-changed" else 0,
                )

    def test_auxiliary_persistence_fence_requires_retry_retention(self):
        pending_snapshot = self._valid_runtime_calibration()
        successful_cases = (
            ("clean-unverified", False, None, False, False, ()),
            (
                "dirty-unverified",
                True,
                pending_snapshot,
                False,
                False,
                (pending_snapshot,),
            ),
            ("changed-verified", False, None, True, True, (None,)),
            (
                "dirty-unchanged-verified",
                True,
                pending_snapshot,
                False,
                True,
                (pending_snapshot,),
            ),
            ("clean-unchanged-verified", False, None, False, True, ()),
        )
        for (
            name,
            previous_dirty,
            previous_snapshot,
            state_changed,
            state_verified,
            expected_retained,
        ) in successful_cases:
            with self.subTest(name=name):
                cancellations = []
                retained = []
                namespace = {
                    "_calibration_dirty": True,
                    "_calibration_save_snapshot": {"stale": "value"},
                    "_cancel_auxiliary_calibration_persistence_job": (
                        lambda: cancellations.append(True)
                    ),
                    "_retain_calibration_persistence_retry": (
                        lambda snapshot=None: retained.append(snapshot) or True
                    ),
                }
                finish = self.compile_function(
                    "_finish_auxiliary_calibration_persistence_fence",
                    namespace,
                )

                self.assertIsNone(
                    finish(
                        previous_dirty,
                        previous_snapshot,
                        state_changed,
                        state_verified,
                    )
                )
                self.assertEqual(cancellations, [True])
                self.assertEqual(retained, list(expected_retained))
                if not expected_retained:
                    self.assertFalse(namespace["_calibration_dirty"])
                    self.assertIsNone(
                        namespace["_calibration_save_snapshot"]
                    )

        failing_cases = (
            ("dirty-unverified", True, pending_snapshot, False, False),
            ("changed-verified", False, None, True, True),
            (
                "dirty-unchanged-verified",
                True,
                pending_snapshot,
                False,
                True,
            ),
        )
        for (
            name,
            previous_dirty,
            previous_snapshot,
            state_changed,
            state_verified,
        ) in failing_cases:
            with self.subTest(name=f"{name}-retention-failed"):
                namespace = {
                    "_calibration_dirty": True,
                    "_calibration_save_snapshot": None,
                    "_cancel_auxiliary_calibration_persistence_job": (
                        lambda: None
                    ),
                    "_retain_calibration_persistence_retry": (
                        lambda snapshot=None: False
                    ),
                }
                finish = self.compile_function(
                    "_finish_auxiliary_calibration_persistence_fence",
                    namespace,
                )

                with self.assertRaisesRegex(
                    RuntimeError,
                    "persistence retry was not retained",
                ):
                    finish(
                        previous_dirty,
                        previous_snapshot,
                        state_changed,
                        state_verified,
                    )

    def test_auxiliary_settle_reconciliation_preserves_persistence_target(self):
        safe_snapshot = self._valid_runtime_calibration()
        for target in (None, safe_snapshot):
            with self.subTest(explicit_snapshot=target is not None):
                retained = []
                namespace = {
                    "_calibration_save_job": None,
                    "_calibration_dirty": False,
                    "_calibration_save_snapshot": None,
                    "_retain_calibration_persistence_retry": (
                        lambda snapshot=None: retained.append(snapshot) or True
                    ),
                    "root": SimpleNamespace(after_cancel=lambda job: None),
                    "logger": SimpleNamespace(
                        error=lambda *args: None,
                        exception=lambda *args: None,
                    ),
                }
                reconcile = self.compile_function(
                    "_reconcile_auxiliary_calibration_persistence_after_settle_failure",
                    namespace,
                )

                self.assertTrue(
                    reconcile(True, target, safe_snapshot)
                )
                self.assertEqual(len(retained), 1)
                if target is None:
                    self.assertIsNone(retained[0])
                else:
                    self.assertEqual(
                        retained[0],
                        normalize_calibration_data(target),
                    )

        exceptions = []
        queued_snapshot = dict(
            safe_snapshot,
            curTheme=(
                1
                if safe_snapshot["curTheme"] == 0
                else 0
            ),
        )

        def fail_cancel(job):
            raise RuntimeError("cancel failed")

        namespace = {
            "_calibration_save_job": "pending-job",
            "_calibration_dirty": True,
            "_calibration_save_snapshot": None,
            "_retain_calibration_persistence_retry": (
                lambda snapshot=None: self.fail(
                    "failed cancellation must not create a second job"
                )
            ),
            "root": SimpleNamespace(after_cancel=fail_cancel),
            "logger": SimpleNamespace(
                error=lambda *args: None,
                exception=lambda *args: exceptions.append(args),
            ),
        }
        reconcile = self.compile_function(
            "_reconcile_auxiliary_calibration_persistence_after_settle_failure",
            namespace,
        )

        self.assertFalse(
            reconcile(True, queued_snapshot, safe_snapshot)
        )
        self.assertTrue(namespace["_calibration_dirty"])
        self.assertEqual(
            namespace["_calibration_save_job"],
            "pending-job",
        )
        self.assertEqual(
            namespace["_calibration_save_snapshot"],
            normalize_calibration_data(queued_snapshot),
        )
        self.assertEqual(len(exceptions), 1)

    def test_shutdown_requests_online_and_offline_stop_before_final_flush(self):
        class Flag:
            def __init__(self, initial=False):
                self.value = initial

            def is_set(self):
                return self.value

            def set(self):
                self.value = True

        class Dispatcher:
            def __init__(self):
                self.closed = False
                self.active = True

            def close(self):
                self.closed = True

        class Label:
            def __init__(self):
                self.text = None

            def config(self, **kwargs):
                self.text = kwargs.get("text")

        class Root:
            def __init__(self):
                self.jobs = []

            def after(self, delay, callback):
                self.jobs.append((delay, callback))

        class Logger:
            def __init__(self):
                self.errors = []

            def error(self, message):
                self.errors.append(message)

        closing = Flag()
        live_pending = Flag(True)
        live_stop = Flag()
        offline_stop = Flag()
        conversion_active = Flag(True)
        conversion_cancel_requested = Flag()
        conversion_tab = SimpleNamespace(GCrunTrue=1)
        dispatcher = Dispatcher()
        first_label = Label()
        second_label = Label()
        root = Root()
        activity = SerialActivityRegistry(("ser", "ser2"))
        poll_calls = []
        namespace = {
            "application_closing": closing,
            "serial_activity_registry": activity,
            "live_serial_result_pending": live_pending,
            "live_jog_stop_requested": live_stop,
            "offline_live_jog_state_lock": threading.Lock(),
            "offline_live_jog_stop_event": offline_stop,
            "gcode_conversion_active": conversion_active,
            "gcode_conversion_cancel_requested": (
                conversion_cancel_requested
            ),
            "gcode_conversion_cancel_lock": threading.Lock(),
            "tab7": conversion_tab,
            "joint_motion_dispatcher": dispatcher,
            "_poll_application_close": lambda: poll_calls.append(True),
            "almStatusLab": first_label,
            "almStatusLab2": second_label,
            "root": root,
        }
        close_application = self.compile_function("on_closing", namespace)

        self.assertTrue(close_application())
        self.assertTrue(closing.is_set())
        self.assertTrue(live_stop.is_set())
        self.assertTrue(offline_stop.is_set())
        self.assertTrue(conversion_cancel_requested.is_set())
        self.assertEqual(conversion_tab.GCrunTrue, 0)
        self.assertTrue(dispatcher.closed)
        with self.assertRaises(SerialActivityRejected):
            activity.begin("ser")
        self.assertEqual(poll_calls, [True])
        self.assertEqual(first_label.text, "SHUTDOWN WAITING FOR CONTROLLER")
        self.assertEqual(second_label.text, first_label.text)
        self.assertFalse(close_application())
        self.assertEqual(poll_calls, [True])

