    def test_shutdown_close_helper_retains_a_port_that_did_not_close(self):
        class Port:
            def __init__(self, closes=True, raises=False):
                self.is_open = True
                self.closes = closes
                self.raises = raises

            def close(self):
                if self.raises:
                    raise OSError("close failed")
                if self.closes:
                    self.is_open = False

        class Logger:
            def __init__(self):
                self.errors = []
                self.exceptions = []

            def error(self, *args):
                self.errors.append(args)

            def exception(self, *args):
                self.exceptions.append(args)

        logger = Logger()
        successful = Port()
        identity_clears = []
        namespace = {
            "RUN": {"ser": successful},
            "_clear_main_controller_identity": (
                lambda serial_port: identity_clears.append(serial_port) or True
            ),
            "logger": logger,
        }
