    def test_auxiliary_output_field_replacement_rolls_back_partial_update(self):
        class Entry:
            def __init__(self, value, fail_on=None):
                self.value = value
                self.fail_on = fail_on

            def get(self):
                return self.value

            def delete(self, *args):
                self.value = ""

            def insert(self, index, value):
                if value == self.fail_on:
                    raise RuntimeError("field update failed")
                self.value = value

        keys = tuple(
            f"DO{output}{state}"
            for output in range(1, 7)
            for state in ("on", "off")
        )
        entries = {
            key: Entry(str(index))
            for index, key in enumerate(keys, start=1)
        }
        entries["DO2on"].fail_on = "broken"
        namespace = {
            f"{key}EntryField": entry
            for key, entry in entries.items()
        }
        namespace.update({
            "MotionInputError": MotionInputError,
            "logger": SimpleNamespace(exception=lambda *args: None),
        })
        namespace["_auxiliary_output_field_bindings"] = self.compile_function(
            "_auxiliary_output_field_bindings",
            namespace,
        )
        read_values = self.compile_function(
            "_read_auxiliary_output_field_values",
            namespace,
        )
        replace_values = self.compile_function(
            "_replace_auxiliary_output_field_values",
            namespace,
        )
        self.assertEqual(
            tuple(
                key
                for key, _ in namespace[
                    "_auxiliary_output_field_bindings"
                ]()
            ),
            tuple(self._auxiliary_output_values({})),
        )
        original = read_values()

        with self.assertRaisesRegex(RuntimeError, "field update failed"):
            replace_values({"DO1on": "8", "DO2on": "broken"})
        self.assertEqual(read_values(), original)

        previous = replace_values({"DO1on": "8"})
        self.assertEqual(previous, original)
        self.assertEqual(read_values()["DO1on"], "8")

    def test_auxiliary_connection_wrapper_enforces_logical_and_shutdown_admission(self):
        def build_namespace(*, closing=False, active=False):
            motion_registry = MotionRequestRegistry()
            if active:
                self.assertIsNotNone(motion_registry.acquire("existing motion"))
            closing_event = threading.Event()
            if closing:
                closing_event.set()
            replacement_calls = []
            calibration = self._valid_runtime_calibration()
            calibration["com2Port"] = "COM2"
            calibration["auxiliaryBoard"] = AUXILIARY_BOARD_MEGA
            output_values = self._auxiliary_output_values(calibration)
            namespace = {
                "wraps": wraps,
                "motion_request_registry": motion_registry,
                "application_closing": closing_event,
                "auxiliary_serial_lock": threading.Lock(),
                "CAL": calibration,
                "RUN": {"ser2": None},
                "com2SelectedValue": SimpleNamespace(
                    get=lambda: "COM9",
                    set=lambda value: None,
                ),
                "auxiliaryBoardSelectedValue": SimpleNamespace(
                    get=lambda: AUXILIARY_BOARD_NANO,
                    set=lambda value: None,
                ),
                "_replace_auxiliary_serial": (
                    lambda port, board: replacement_calls.append((port, board))
                ),
                "_read_auxiliary_output_field_values": (
                    lambda: dict(output_values)
                ),
                "_replace_auxiliary_output_field_values": lambda values: {},
                "_close_serial_port": lambda *args: True,
                "logger": SimpleNamespace(
                    info=lambda *args: None,
                    warning=lambda *args: None,
                    error=lambda *args: None,
                    exception=lambda *args: None,
                ),
                "tab8": SimpleNamespace(ElogView=SimpleNamespace(get=lambda *args: ())),
                "pickle": SimpleNamespace(dump=lambda *args: None),
                "open": lambda *args, **kwargs: object(),
                "END": "end",
            }
            namespace["_synchronous_motion_request"] = self.compile_function(
                "_synchronous_motion_request",
                namespace,
            )
            callback = self.compile_function(
                "setCom2",
                namespace,
                preserve_decorators=True,
            )
            return callback, namespace, replacement_calls

        for closing, active in ((True, False), (False, True)):
            with self.subTest(closing=closing, active=active):
                callback, namespace, replacement_calls = build_namespace(
                    closing=closing,
                    active=active,
                )
                self.assertFalse(callback())
                self.assertEqual(replacement_calls, [])
                self.assertFalse(namespace["auxiliary_serial_lock"].locked())
                self.assertEqual(namespace["CAL"]["com2Port"], "COM2")

    def test_auxiliary_connection_transaction_reconciles_failure_state(self):
        class Selection:
            def __init__(self, value):
                self.value = value
                self.set_calls = []

            def get(self):
                return self.value

            def set(self, value):
                self.value = value
                self.set_calls.append(value)

        def run_case(
            replacement_error=None,
            disable_close=True,
            disable=False,
            follow_up_error=None,
            settle_failure=False,
            reconciliation_result=True,
            reconciliation_exception=None,
            persistence_result=True,
            initial_dirty=False,
            verification_failure=False,
        ):
            if (
                not settle_failure
                and (
                    reconciliation_result is not True
                    or reconciliation_exception is not None
                )
            ):
                raise ValueError(
                    "reconciliation controls require settle_failure"
                )
            port_selection = Selection("None" if disable else "COM9")
            board_selection = Selection(
                AUXILIARY_BOARD_NONE if disable else AUXILIARY_BOARD_NANO
            )
            calibration = self._valid_runtime_calibration()
            calibration["com2Port"] = "COM2"
            calibration["auxiliaryBoard"] = AUXILIARY_BOARD_MEGA
            runtime = {"ser2": SimpleNamespace(is_open=True) if disable else None}
            replacement_calls = []
            persistence_calls = []
            reconciliation_calls = []
            error_calls = []
            exception_calls = []
            output_values = self._auxiliary_output_values(calibration)

            def replace(port, board):
                replacement_calls.append((port, board))
                if replacement_error is not None:
                    raise replacement_error

            def retain_persistence(calibration_snapshot=None):
                persistence_calls.append(
                    dict(
                        calibration
                        if calibration_snapshot is None
                        else calibration_snapshot
                    )
                )
                return persistence_result

            def replace_output_values(values):
                previous = dict(output_values)
                for key in output_values:
                    output_values[key] = str(values[key])
                return previous

            def log_connection(*args):
                if follow_up_error is not None:
                    raise follow_up_error

            def finish_persistence(*args):
                if settle_failure:
                    raise RuntimeError("persistence settle failed")

            def reconcile_persistence(required, snapshot, safe_snapshot):
                reconciliation_calls.append(
                    (required, snapshot, safe_snapshot)
                )
                if reconciliation_exception is not None:
                    raise reconciliation_exception
                return reconciliation_result

            def verify_configuration(*args):
                if verification_failure:
                    raise RuntimeError("configuration verification failed")
                return True

            namespace = {
                "_calibration_dirty": initial_dirty,
                "_calibration_save_job": (
                    "pending-job"
                    if initial_dirty
                    else None
                ),
                "_calibration_save_snapshot": None,
                "root": SimpleNamespace(after_cancel=lambda job: None),
                "wraps": wraps,
                "motion_request_registry": MotionRequestRegistry(),
                "application_closing": threading.Event(),
                "auxiliary_serial_lock": threading.Lock(),
                "CAL": calibration,
                "RUN": runtime,
                "com2SelectedValue": port_selection,
                "auxiliaryBoardSelectedValue": board_selection,
                "_replace_auxiliary_serial": replace,
                "_read_auxiliary_output_field_values": (
                    lambda: dict(output_values)
                ),
                "_replace_auxiliary_output_field_values": (
                    replace_output_values
                ),
                "_close_serial_port": lambda *args: disable_close,
                "_retain_calibration_persistence_retry": retain_persistence,
                "logger": SimpleNamespace(
                    info=log_connection,
                    warning=lambda *args: None,
                    error=lambda *args: error_calls.append(args),
                    exception=lambda *args: exception_calls.append(args),
                ),
                "tab8": SimpleNamespace(ElogView=SimpleNamespace(get=lambda *args: ())),
                "pickle": SimpleNamespace(dump=lambda *args: None),
                "open": lambda *args, **kwargs: object(),
                "END": "end",
            }
            if settle_failure:
                namespace[
                    "_finish_auxiliary_calibration_persistence_fence"
                ] = finish_persistence
                namespace[
                    "_reconcile_auxiliary_calibration_persistence_after_settle_failure"
                ] = reconcile_persistence
            if verification_failure:
                namespace[
                    "_verify_auxiliary_configuration_snapshot"
                ] = verify_configuration
            namespace["_synchronous_motion_request"] = self.compile_function(
                "_synchronous_motion_request",
                namespace,
            )
            callback = self.compile_function(
                "setCom2",
                namespace,
                preserve_decorators=True,
            )
            result = callback()
            self.assertFalse(namespace["motion_request_registry"].active)
            self.assertFalse(namespace["auxiliary_serial_lock"].locked())
            return (
                result,
                calibration,
                port_selection,
                board_selection,
                replacement_calls,
                persistence_calls,
                reconciliation_calls,
                error_calls,
                exception_calls,
            )

        success = run_case()
        self.assertTrue(success[0])
        self.assertEqual(success[1]["com2Port"], "COM9")
        self.assertEqual(success[1]["auxiliaryBoard"], AUXILIARY_BOARD_NANO)
        self.assertEqual(
            success[4],
            [("COM9", AUXILIARY_BOARD_NANO)],
        )
        self.assertEqual(
            success[5][0]["com2Port"],
            "COM9",
        )
        self.assertEqual(
            success[5][0]["auxiliaryBoard"],
            AUXILIARY_BOARD_NANO,
        )

        reconciliation_error = (
            "Auxiliary calibration persistence reconciliation "
            "did not complete",
        )
        persistence_failure = run_case(persistence_result=False)
        self.assertFalse(persistence_failure[0])
        self.assertEqual(persistence_failure[1]["com2Port"], "COM9")
        self.assertEqual(
            persistence_failure[1]["auxiliaryBoard"],
            AUXILIARY_BOARD_NANO,
        )
        self.assertEqual(len(persistence_failure[5]), 3)
        self.assertIn(reconciliation_error, persistence_failure[7])
        self.assertTrue(
            any(
                call
                and call[0]
                == "AUXILIARY CONNECTION CHANGED BUT FOLLOW-UP FAILED: %s"
                for call in persistence_failure[7]
            )
        )

        open_failure = run_case(replacement_error=OSError("open failed"))
        self.assertFalse(open_failure[0])
        self.assertEqual(open_failure[1]["com2Port"], "COM2")
        self.assertEqual(
            open_failure[1]["auxiliaryBoard"],
            AUXILIARY_BOARD_MEGA,
        )
        self.assertEqual(open_failure[2].set_calls, ["COM2"])
        self.assertEqual(
            open_failure[3].set_calls,
            [AUXILIARY_BOARD_MEGA],
        )
        self.assertEqual(open_failure[5], [])

        close_failure = run_case(disable=True, disable_close=False)
        self.assertFalse(close_failure[0])
        self.assertEqual(close_failure[1]["com2Port"], "COM2")
        self.assertEqual(close_failure[1]["auxiliaryBoard"], AUXILIARY_BOARD_MEGA)
        self.assertEqual(close_failure[2].set_calls, ["COM2"])
        self.assertEqual(
            close_failure[3].set_calls,
            [AUXILIARY_BOARD_MEGA],
        )
        self.assertEqual(close_failure[5], [])

        follow_up_failure = run_case(
            follow_up_error=RuntimeError("logging failed"),
        )
        self.assertFalse(follow_up_failure[0])
        self.assertEqual(follow_up_failure[1]["com2Port"], "COM9")
        self.assertEqual(
            follow_up_failure[1]["auxiliaryBoard"],
            AUXILIARY_BOARD_NANO,
        )
        self.assertEqual(follow_up_failure[2].set_calls, ["COM9"])
        self.assertEqual(
            follow_up_failure[3].set_calls,
            [AUXILIARY_BOARD_NANO],
        )
        self.assertEqual(
            follow_up_failure[4],
            [("COM9", AUXILIARY_BOARD_NANO)],
        )
        self.assertEqual(len(follow_up_failure[5]), 1)
        self.assertEqual(
            follow_up_failure[5][0]["com2Port"],
            "COM9",
        )

        settle_failure = run_case(settle_failure=True)
        self.assertFalse(settle_failure[0])
        self.assertEqual(settle_failure[1]["com2Port"], "COM9")
        self.assertEqual(
            settle_failure[1]["auxiliaryBoard"],
            AUXILIARY_BOARD_NANO,
        )
        self.assertEqual(len(settle_failure[6]), 1)
        self.assertTrue(settle_failure[6][0][0])
        self.assertIsNone(settle_failure[6][0][1])
        self.assertEqual(
            settle_failure[6][0][2]["com2Port"],
            "COM9",
        )
        self.assertEqual(
            settle_failure[6][0][2]["auxiliaryBoard"],
            AUXILIARY_BOARD_NANO,
        )
        self.assertNotIn(reconciliation_error, settle_failure[7])

        unreconciled_settle_failure = run_case(
            settle_failure=True,
            reconciliation_result=False,
        )
        self.assertFalse(unreconciled_settle_failure[0])
        self.assertIn(
            reconciliation_error,
            unreconciled_settle_failure[7],
        )

        reconciliation_exception = run_case(
            settle_failure=True,
            reconciliation_exception=RuntimeError(
                "persistence reconciliation failed"
            ),
        )
        self.assertFalse(reconciliation_exception[0])
        self.assertIn(
            (
                "Unable to reconcile calibration persistence "
                "after settle failure",
            ),
            reconciliation_exception[8],
        )

        restored_settle_failure = run_case(
            replacement_error=OSError("open failed"),
            settle_failure=True,
        )
        self.assertFalse(restored_settle_failure[0])
        self.assertEqual(len(restored_settle_failure[6]), 1)
        self.assertFalse(restored_settle_failure[6][0][0])
        self.assertIsNone(restored_settle_failure[6][0][1])
        self.assertEqual(
            restored_settle_failure[6][0][2]["com2Port"],
            "COM2",
        )

        dirty_restored_settle_failure = run_case(
            replacement_error=OSError("open failed"),
            settle_failure=True,
            initial_dirty=True,
        )
        self.assertFalse(dirty_restored_settle_failure[0])
        self.assertEqual(len(dirty_restored_settle_failure[6]), 1)
        self.assertTrue(dirty_restored_settle_failure[6][0][0])
        self.assertEqual(
            dirty_restored_settle_failure[6][0][1]["com2Port"],
            "COM2",
        )
        self.assertEqual(
            dirty_restored_settle_failure[6][0][2]["com2Port"],
            "COM2",
        )

        clean_unverified_settle_failure = run_case(
            settle_failure=True,
            verification_failure=True,
        )
        self.assertFalse(clean_unverified_settle_failure[0])
        self.assertEqual(len(clean_unverified_settle_failure[6]), 1)
        self.assertFalse(clean_unverified_settle_failure[6][0][0])
        self.assertIsNone(clean_unverified_settle_failure[6][0][1])
        self.assertEqual(
            clean_unverified_settle_failure[6][0][2]["com2Port"],
            "COM2",
        )

        unverified_settle_failure = run_case(
            settle_failure=True,
            verification_failure=True,
            initial_dirty=True,
        )
        self.assertFalse(unverified_settle_failure[0])
        self.assertEqual(len(unverified_settle_failure[6]), 1)
        self.assertTrue(unverified_settle_failure[6][0][0])
        self.assertEqual(
            unverified_settle_failure[6][0][1]["com2Port"],
            "COM2",
        )
        self.assertEqual(
            unverified_settle_failure[6][0][2]["com2Port"],
            "COM2",
        )

