    def test_if_input_row_builder_composes_with_auxiliary_validation(self):
        class ProgramView:
            def __init__(self):
                self.rows = [b"Tab Number 1\n"]
                self.selected = 0

            def curselection(self):
                return (self.selected,)

            def index(self, value):
                if value != "end":
                    raise AssertionError("unexpected program-view index")
                return len(self.rows)

            def insert(self, index, row):
                self.rows.insert(index, row)

            def selection_clear(self, *args):
                self.selected = None

            def select_set(self, index):
                self.selected = index

            def see(self, *args):
                pass

            def get(self, first, last=None):
                if last is not None:
                    return tuple(self.rows)
                return self.rows[first]

        class Entry:
            def __init__(self, value=""):
                self.value = value

            def get(self):
                return self.value

            def delete(self, *args):
                self.value = ""

            def insert(self, index, value):
                self.value = value

        view = ProgramView()
        builder_namespace = {
            "tab1": SimpleNamespace(progView=view),
            "iFoption": Entry("5v Input"),
            "iFselection": Entry("Stop"),
            "IfVarEntryField": Entry("2"),
            "IfInputEntryField": Entry("1"),
            "IfDestEntryField": Entry(""),
            "ProgEntryField": Entry("ignored.ar4"),
            "END": "end",
            "path": SimpleNamespace(relpath=lambda value: value),
            "open": lambda *args, **kwargs: io.StringIO(),
            "_set_application_status": lambda **kwargs: True,
        }
        insert_if = self.compile_function("IfCMDInsert", builder_namespace)

        insert_if()

        self.assertEqual(view.rows[1], b"If Input # 2 = 1 : Stop \n")
        transmitted = []
        sent_field = Entry()

        def execute_auxiliary(command, **contract):
            validate_auxiliary_input_command(command, AUXILIARY_BOARD_NANO)
            transmitted.append((command, contract))
            return "complete", "F"

        runtime = {
            "estopActive": False,
            "posOutreach": False,
            "programStopRequestId": None,
            "programStopStatusLatched": False,
            "progRunning": False,
            "rowinproc": 0,
            "offlineMode": False,
            "moveInProc": 0,
        }
        execute_namespace = {
            "RUN": runtime,
            "tab1": SimpleNamespace(progView=view),
            "program_stop_state_lock": threading.RLock(),
            "cmdSentEntryField": sent_field,
            "_execute_row_auxiliary_command": execute_auxiliary,
            "_finish_execute_row": lambda: None,
            "_set_application_status": lambda *args, **kwargs: True,
            "stopProg": lambda: self.fail("mismatched input must not stop"),
            "ROW_EXECUTION_COMPLETE": "complete",
            "ROW_EXECUTION_PENDING": "pending",
            "ROW_EXECUTION_REJECTED": "rejected",
            "logger": SimpleNamespace(
                warning=lambda *args: None,
                error=lambda *args: None,
                exception=lambda *args: None,
            ),
            "END": "end",
        }
        execute_row = self.compile_function("executeRow", execute_namespace)

        self.assertEqual(execute_row(), "complete")
        self.assertEqual(sent_field.value, "JFX2\n")
        self.assertEqual(
            transmitted,
            [
                (
                    "JFX2\n",
                    {
                        "read_line": True,
                        "accepted_responses": ("T", "F"),
                    },
                ),
            ],
        )

    def test_main_wait_contract_matches_teensy_numeric_and_response_types(self):
        namespace = {
            "MotionInputError": MotionInputError,
            "MAIN_FIRMWARE_WAIT_MAX_SECONDS": 2147483,
            "re": re,
            "finite_number": finite_number,
            "controller_protocol_decimal": controller_protocol_decimal,
        }
        validate_modbus = self.compile_function(
            "_main_modbus_wait_timeout_seconds",
            namespace,
        )
        validate_timed = self.compile_function(
            "_main_timed_wait_seconds",
            namespace,
        )

        self.assertEqual(validate_modbus("1"), 1)
        self.assertEqual(validate_modbus("2147483"), 2147483)
        for value in (True, 0, -1, 1.5, "2147484", "1e2"):
            with self.subTest(value=value):
                with self.assertRaises(MotionInputError):
                    validate_modbus(value)
        self.assertEqual(validate_timed("0.5"), (0.5, "0.5"))
        for value in (-1, "2147484", float("inf")):
            with self.subTest(value=value):
                with self.assertRaises(MotionInputError):
                    validate_timed(value)

        firmware = TEENSY_SOURCE.read_text(encoding="utf-8")
        for opcode, next_opcode in (("WJ", "WK"), ("WK", "SC")):
            branch_start = firmware.index(f'if (function == "{opcode}")')
            branch_end = firmware.index(
                f'if (function == "{next_opcode}")',
                branch_start,
            )
            branch = firmware[branch_start:branch_end]
            self.assertIn('Serial.println("Done")', branch)
            self.assertIn('Serial.println("Modbus Error")', branch)
            self.assertIn('Serial.println("ER")', branch)
        wait_start = firmware.index('if (function == "WT")')
        wait_end = firmware.index(
            'if (function == "ON" || function == "OF")',
            wait_start,
        )
        self.assertIn('Serial.println("WTdone")', firmware[wait_start:wait_end])

    def test_program_modbus_responses_fail_before_row_completion(self):
        class Label:
            def __init__(self):
                self.text = None

            def config(self, **kwargs):
                self.text = kwargs.get("text")

        response = {"value": "1"}
        finishes = []
        first_label = Label()
        second_label = Label()
        namespace = {
            "ROW_EXECUTION_COMPLETE": "complete",
            "ROW_EXECUTION_REJECTED": "rejected",
            "ProtocolResponseError": ProtocolResponseError,
            "_execute_row_main_command": (
                lambda command, **contract: ("complete", response["value"])
            ),
            "_finish_execute_row": lambda: finishes.append(True),
            "logger": SimpleNamespace(error=lambda *args: None),
            "almStatusLab": first_label,
            "almStatusLab2": second_label,
        }
        execute = self.compile_function(
            "_execute_row_main_response",
            namespace,
        )

        self.assertEqual(
            execute(
                "BAA1B0C1\n",
                response_parser=parse_controller_modbus_response,
            ),
            ("complete", "1"),
        )
        self.assertEqual(finishes, [])

        for rejected in ("ER", "Modbus Error", "-1", "unexpected"):
            with self.subTest(rejected=rejected):
                response["value"] = rejected
                self.assertEqual(
                    execute(
                        "BAA1B0C1\n",
                        response_parser=parse_controller_modbus_response,
                    ),
                    ("rejected", None),
                )
        self.assertEqual(len(finishes), 4)
        self.assertIn("response rejected", first_label.text)
        self.assertEqual(first_label.text, second_label.text)

        execute_row_source = ast.get_source_segment(
            AR4_SOURCE.read_text(encoding="utf-8"),
            self.module_functions["executeRow"],
        )
        self.assertNotIn('response == "Modbus Error"', execute_row_source)
        self.assertNotIn('response == "-1"', execute_row_source)
        self.assertGreaterEqual(
            execute_row_source.count(
                "response_parser=parse_controller_modbus_response"
            ),
            6,
        )
        self.assertGreaterEqual(
            execute_row_source.count(
                "_execute_row_main_modbus_write_response"
            ),
            2,
        )

    def test_program_modbus_writes_preserve_indeterminate_external_state(self):
        class Port:
            def __init__(self):
                self.is_open = True

            def close(self):
                self.is_open = False

        response = {"value": "1"}
        runtime = {"ser": None}
        finishes = []
        statuses = []
        invalidations = []
        identity_cleanup = []
        command_calls = []
        namespace = {
            "ROW_EXECUTION_COMPLETE": "complete",
            "ROW_EXECUTION_REJECTED": "rejected",
            "MotionInputError": MotionInputError,
            "ProtocolResponseError": ProtocolResponseError,
            "MAX_RESPONSE_PAYLOAD_LENGTH": MAX_RESPONSE_PAYLOAD_LENGTH,
            "controller_modbus_command_is_write": (
                controller_modbus_command_is_write
            ),
            "classify_controller_modbus_terminal_response": (
                classify_controller_modbus_terminal_response
            ),
            "quarantine_serial_transport": quarantine_serial_transport,
            "RUN": runtime,
            "_execute_row_main_command": (
                lambda command: (
                    command_calls.append(command)
                    or ("complete", response["value"])
                )
            ),
            "_require_main_controller_identity_cleanup": (
                lambda port, context: (
                    identity_cleanup.append((port, context)) or True
                )
            ),
            "_clear_auxiliary_board_profile": lambda port=None: True,
            "_invalidate_joint_motion_state": invalidations.append,
            "_set_application_status": (
                lambda message, style: (
                    statuses.append((message, style)) or True
                )
            ),
            "_finish_execute_row": lambda: finishes.append(True),
            "logger": SimpleNamespace(
                error=lambda *args: None,
                exception=lambda *args: None,
            ),
        }
        namespace["_close_serial_port"] = self.compile_function(
            "_close_serial_port",
            namespace,
        )
        namespace["_reject_indeterminate_program_modbus_write"] = (
            self.compile_function(
                "_reject_indeterminate_program_modbus_write",
                namespace,
            )
        )
        execute_write = self.compile_function(
            "_execute_row_main_modbus_write_response",
            namespace,
        )

        for opcode in ("SC", "SO"):
            with self.subTest(indeterminate_opcode=opcode):
                port = Port()
                runtime["ser"] = port
                response["value"] = "-1"
                result = execute_write(f"{opcode}A1B0C1\n")

                self.assertEqual(result, ("rejected", None))
                self.assertFalse(port.is_open)
                self.assertIsNone(runtime["ser"])
                self.assertTrue(serial_transport_quarantined(port))
                self.assertIs(identity_cleanup[-1][0], port)
                self.assertIn(
                    f"program Modbus {opcode} external write outcome is unknown",
                    invalidations[-1],
                )
                self.assertIn("write outcome unknown", statuses[-1][0])
                self.assertIn(
                    "verify external device state",
                    statuses[-1][0],
                )

        completed_port = Port()
        runtime["ser"] = completed_port
        response["value"] = "1"
        finish_count = len(finishes)
        self.assertEqual(
            execute_write("SCA1B0C1\n"),
            ("complete", "1"),
        )
        self.assertTrue(completed_port.is_open)
        self.assertEqual(len(finishes), finish_count)

        response["value"] = "-2"
        self.assertEqual(
            execute_write("SOA1B0C1\n"),
            ("rejected", None),
        )
        self.assertTrue(completed_port.is_open)
        self.assertEqual(len(finishes), finish_count + 1)
        self.assertIn("write rejected: -2", statuses[-1][0])

        unexpected_port = Port()
        runtime["ser"] = unexpected_port
        response["value"] = "unexpected"
        self.assertEqual(
            execute_write("SCA1B0C1\n"),
            ("rejected", None),
        )
        self.assertFalse(unexpected_port.is_open)
        self.assertIsNone(runtime["ser"])
        self.assertIn("write outcome unknown", statuses[-1][0])

        command_count = len(command_calls)
        with self.assertRaisesRegex(MotionInputError, "SC or SO"):
            execute_write("BAA1B0C1\n")
        self.assertEqual(len(command_calls), command_count)

    def test_program_modbus_register_rows_canonicalize_or_reject_before_exchange(self):
        builder_namespace = {
            "MotionInputError": MotionInputError,
            "build_controller_modbus_command": build_controller_modbus_command,
            "re": re,
        }
        build_program_read = self.compile_function(
            "_build_program_modbus_register_read",
            builder_namespace,
        )
        self.assertEqual(
            build_program_read("BH", "3", "42", "1"),
            "BHA3B42C1\n",
        )
        self.assertEqual(
            build_program_read("BD", "4", "43", "1"),
            "BDA4B43C1\n",
        )
        for opcode in ("BH", "BD"):
            with self.subTest(migration_opcode=opcode):
                with self.assertRaisesRegex(
                    MotionInputError,
                    "legacy multi-register read requires migration",
                ):
                    build_program_read(opcode, "1", "42", "2")

        class ProgramView:
            def __init__(self):
                self.row = b""

            @staticmethod
            def curselection():
                return (0,)

            @staticmethod
            def see(*args):
                pass

            def get(self, *args):
                return self.row

        view = ProgramView()
        transmissions = []
        finishes = []
        statuses = []
        runtime = {
            "estopActive": False,
            "posOutreach": False,
            "programStopRequestId": None,
            "programStopStatusLatched": False,
            "progRunning": False,
            "rowinproc": 0,
            "offlineMode": False,
            "moveInProc": 0,
        }
        namespace = {
            "RUN": runtime,
            "tab1": SimpleNamespace(progView=view),
            "ROW_EXECUTION_COMPLETE": "complete",
            "ROW_EXECUTION_PENDING": "pending",
            "ROW_EXECUTION_REJECTED": "rejected",
            "MotionInputError": MotionInputError,
            "parse_controller_modbus_response": (
                parse_controller_modbus_response
            ),
            "_build_program_modbus_register_read": build_program_read,
            "_execute_row_main_response": (
                lambda command, **contract: (
                    transmissions.append((command, contract))
                    or ("complete", "0")
                )
            ),
            "_finish_execute_row": lambda: finishes.append(True),
            "_set_application_status": (
                lambda message, style: statuses.append((message, style))
                or True
            ),
            "logger": SimpleNamespace(error=lambda *args: None),
        }
        execute_row = self.compile_function("executeRow", namespace)
        row_templates = {
            "BH": (
                "If MBhold reg - SlaveID (3) Num Reg's ({quantity}) "
                "- Reg # 42 = 99 :"
            ),
            "BD": (
                "If MBInput Reg - SlaveID (4) Num Reg's ({quantity}) "
                "- Input Reg # 43 = 99 :"
            ),
        }
        expected_commands = {
            "BH": "BHA3B42C1\n",
            "BD": "BDA4B43C1\n",
        }

        for opcode, row_template in row_templates.items():
            with self.subTest(opcode=opcode, quantity=1):
                view.row = row_template.format(quantity=1).encode("utf-8")
                transmissions.clear()
                statuses.clear()
                self.assertEqual(execute_row(), "complete")
                self.assertEqual(
                    transmissions,
                    [
                        (
                            expected_commands[opcode],
                            {
                                "response_parser": (
                                    parse_controller_modbus_response
                                ),
                            },
                        ),
                    ],
                )
                self.assertEqual(statuses, [])

            with self.subTest(opcode=opcode, quantity=2):
                view.row = row_template.format(quantity=2).encode("utf-8")
                transmissions.clear()
                statuses.clear()
                self.assertEqual(execute_row(), "rejected")
                self.assertEqual(transmissions, [])
                self.assertEqual(len(statuses), 1)
                self.assertIn(
                    "legacy multi-register read requires migration",
                    statuses[0][0],
                )

        def cancel_during_exchange(command, **contract):
            transmissions.append((command, contract))
            namespace["program_execution_cancelled"].set()
            return "complete", "99"

        namespace["_execute_row_main_response"] = cancel_during_exchange
        view.row = (
            "If MBhold reg - SlaveID (3) Num Reg's (1) "
            "- Reg # 42 = 99 : Jump Tab 2"
        ).encode("utf-8")
        transmissions.clear()
        statuses.clear()
        runtime["progRunning"] = True
        runtime["rowinproc"] = 1
        self.assertEqual(execute_row(), "rejected")
        self.assertEqual(
            [command for command, _ in transmissions],
            ["BHA3B42C1\n"],
        )
        self.assertEqual(statuses, [])
        self.assertEqual(len(finishes), 4)
        self.assertFalse(runtime["progRunning"])
        self.assertEqual(runtime["rowinproc"], 0)

    def test_injectable_auxiliary_command_requires_validated_line_ownership(self):
        execute_auxiliary = self.compile_function(
            "_execute_row_auxiliary_command",
            {
                "finite_number": finite_number,
                "MotionInputError": MotionInputError,
                "SERIAL_AUXILIARY_RESPONSE_TIMEOUT_SECONDS": 5,
            },
        )

        with self.assertRaisesRegex(
            MotionInputError,
            "validated line responses",
        ):
            execute_auxiliary("WIA2B1C30\n", control_injectable=True)

        with self.assertRaisesRegex(TypeError, "parser must be callable"):
            execute_auxiliary(
                "TG\n",
                read_line=True,
                response_parser="not-callable",
            )
        with self.assertRaisesRegex(
            MotionInputError,
            "line-response ownership",
        ):
            execute_auxiliary(
                "TG\n",
                expected_response=b"Done",
                response_parser=lambda command, response: response,
            )
        with self.assertRaisesRegex(
            MotionInputError,
            "one validation contract",
        ):
            execute_auxiliary(
                "TG\n",
                read_line=True,
                accepted_responses=("0.000",),
                response_parser=lambda command, response: response,
            )

