    def test_program_stop_remains_pending_until_auxiliary_terminal_event(self):
        class Label:
            def __init__(self):
                self.text = None

            def config(self, **kwargs):
                self.text = kwargs.get("text")

        first_label = Label()
        second_label = Label()
        cancelled = []
        stop_barrier = threading.Event()

        def begin_stop(reason):
            stop_barrier.set()
            cancelled.append(reason)
            return 2

        runtime = {
            "estopActive": False,
            "posOutreach": False,
            "programStopRequestId": None,
        }

        def request_stop(on_reserved):
            on_reserved(8)
            return "pending", 8

        namespace = {
            "_request_auxiliary_stop": request_stop,
            "tab1": SimpleNamespace(runTrue=1),
            "RUN": runtime,
            "logger": SimpleNamespace(exception=lambda *args: None),
            "almStatusLab": first_label,
            "almStatusLab2": second_label,
            "AUXILIARY_STOP_NOT_REQUIRED": "not-required",
            "manual_auxiliary_stop_barrier": stop_barrier,
            "_begin_manual_auxiliary_stop": begin_stop,
            "_clear_manual_auxiliary_stop_barrier_if_settled": (
                lambda: stop_barrier.clear() or True
            ),
        }
        namespace["_set_program_stop_status"] = self.compile_function(
            "_set_program_stop_status",
            namespace,
        )
        apply_status = self.compile_function(
            "_apply_program_stop_status_events",
            namespace,
        )
        stop_program = self.compile_function("stopProg", namespace)

        stop_program()
        apply_status()

        self.assertEqual(runtime["programStopRequestId"], 8)
        self.assertEqual(runtime["programStopState"], "pending")
        self.assertTrue(runtime["programStopStatusLatched"])
        self.assertTrue(stop_barrier.is_set())
        self.assertEqual(cancelled, ["program stop requested"])
        self.assertEqual(
            first_label.text,
            "PROGRAM HALT REQUESTED; AUXILIARY STOP PENDING; "
            "ACTIVE MAIN MOTION NOT PREEMPTED",
        )
        self.assertEqual(second_label.text, first_label.text)

    def test_program_stop_status_renders_only_when_tk_poll_applies_queue(self):
        class StateLock:
            def __init__(self):
                self.lock = threading.RLock()
                self.depth = 0

            def __enter__(self):
                self.lock.acquire()
                self.depth += 1
                return self

            def __exit__(self, *args):
                self.depth -= 1
                self.lock.release()

        state_lock = StateLock()
        rendered = []

        class Label:
            def config(self, **kwargs):
                self.assert_unlocked()
                rendered.append(kwargs)

            def assert_unlocked(self):
                if state_lock.depth:
                    raise AssertionError(
                        "program-stop status rendered while state lock was held"
                    )

        namespace = {
            "program_stop_state_lock": state_lock,
            "RUN": {
                "estopActive": False,
                "posOutreach": False,
            },
            "almStatusLab": Label(),
            "almStatusLab2": Label(),
        }
        set_status = self.compile_function(
            "_set_program_stop_status",
            namespace,
        )
        apply_status = self.compile_function(
            "_apply_program_stop_status_events",
            namespace,
        )

        worker = threading.Thread(target=lambda: set_status("pending"))
        worker.start()
        worker.join(1)

        self.assertFalse(worker.is_alive())
        self.assertEqual(rendered, [])
        self.assertTrue(apply_status())
        self.assertEqual(len(rendered), 2)
        self.assertFalse(apply_status())

        class FailOnceLabel(Label):
            def __init__(self):
                self.pending_failure = True

            def config(self, **kwargs):
                self.assert_unlocked()
                if self.pending_failure:
                    self.pending_failure = False
                    raise RuntimeError("program-stop status unavailable")
                rendered.append(kwargs)

        namespace["almStatusLab2"] = FailOnceLabel()
        self.assertTrue(set_status("failed"))
        with self.assertRaisesRegex(
            RuntimeError,
            "program-stop status unavailable",
        ):
            apply_status()
        self.assertTrue(set_status("completed"))
        self.assertIsNotNone(
            namespace["program_stop_status_pending_event"]
        )
        self.assertEqual(
            namespace["program_stop_status_event_queue"].qsize(),
            1,
        )
        self.assertTrue(apply_status())
        self.assertIsNone(
            namespace["program_stop_status_pending_event"]
        )
        self.assertTrue(
            namespace["program_stop_status_event_queue"].empty()
        )
        self.assertEqual(
            rendered[-1]["text"],
            "PROGRAM SCHEDULING HALTED; "
            "ACTIVE MAIN MOTION NOT PREEMPTED",
        )

