    def test_mode_change_rejects_every_physical_and_virtual_owner(self):
        owner_names = (
            "virtual",
            "controller-live",
            "legacy-serial",
            "dispatcher",
            "serial-lock",
            "controller-correction",
        )
        for owner_name in owner_names:
            with self.subTest(owner=owner_name):
                live_pending = threading.Event()
                legacy_pending = threading.Event()
                serial_lock = threading.Lock()
                dispatcher = SimpleNamespace(active=False)
                virtual_active = {"value": False}
                correction_requested = threading.Event()
                if owner_name == "virtual":
                    virtual_active["value"] = True
                elif owner_name == "controller-live":
                    live_pending.set()
                elif owner_name == "legacy-serial":
                    legacy_pending.set()
                elif owner_name == "dispatcher":
                    dispatcher.active = True
                elif owner_name == "serial-lock":
                    serial_lock.acquire()
                elif owner_name == "controller-correction":
                    correction_requested.set()

                @contextmanager
                def reserve_mode_transport():
                    if not serial_lock.acquire(blocking=False):
                        raise SerialActivityRejected(
                            "controller transport is busy"
                        )
                    try:
                        yield
                    finally:
                        serial_lock.release()

                requests = []
                runtime = {"offlineMode": False, "VR_angles": [1.0] * 6}
                namespace = {
                    "RUN": runtime,
                    "application_closing": threading.Event(),
                    "_virtual_motion_active": (
                        lambda ignored=None: virtual_active["value"]
                    ),
                    "live_serial_result_pending": live_pending,
                    "legacy_serial_result_pending": legacy_pending,
                    "joint_motion_dispatcher": dispatcher,
                    "serial_lock": serial_lock,
                    "controller_correction_requested": correction_requested,
                    "_reserve_main_serial_operation": reserve_mode_transport,
                    "SerialActivityRejected": SerialActivityRejected,
                    "logger": SimpleNamespace(warning=lambda *args: None),
                    "almStatusLab": SimpleNamespace(config=lambda **kwargs: None),
                    "almStatusLab2": SimpleNamespace(config=lambda **kwargs: None),
                    "requestPos": lambda: requests.append(True),
                }
                namespace["_mode_change_is_blocked"] = self.compile_function(
                    "_mode_change_is_blocked",
                    namespace,
                )
                toggle = self.compile_function("toggle_offline_mode", namespace)

                try:
                    self.assertFalse(toggle())
                    self.assertFalse(runtime["offlineMode"])
                    self.assertEqual(requests, [])
                    self.assertEqual(
                        correction_requested.is_set(),
                        owner_name == "controller-correction",
                    )
                finally:
                    if serial_lock.locked():
                        serial_lock.release()

    def test_mode_transition_holds_motion_and_transport_through_commit(self):
        class Widget:
            def config(self, **kwargs):
                pass

        serial_lock = threading.Lock()
        registry = MotionRequestRegistry()
        attempts = []

        @contextmanager
        def reserve_mode_transport():
            if not serial_lock.acquire(blocking=False):
                raise SerialActivityRejected("controller transport is busy")
            try:
                yield
            finally:
                serial_lock.release()

        def request_position():
            def attempt_competing_motion():
                transport_acquired = serial_lock.acquire(blocking=False)
                if transport_acquired:
                    serial_lock.release()
                lease = registry.acquire("Concurrent program motion")
                motion_acquired = lease is not None
                if lease is not None:
                    lease.close()
                attempts.append((transport_acquired, motion_acquired))

            worker = threading.Thread(target=attempt_competing_motion)
            worker.start()
            worker.join(2)
            self.assertFalse(worker.is_alive())
            return True

        runtime = {"offlineMode": True, "VR_angles": [9.0] * 6}
        namespace = {
            "RUN": runtime,
            "CAL": {f"J{axis}AngCur": str(axis) for axis in range(1, 7)},
            "motion_request_registry": registry,
            "serial_lock": serial_lock,
            "application_closing": threading.Event(),
            "controller_correction_requested": threading.Event(),
            "live_serial_result_pending": threading.Event(),
            "legacy_serial_result_pending": threading.Event(),
            "joint_motion_dispatcher": SimpleNamespace(active=False),
            "_virtual_motion_active": lambda ignored=None: False,
            "_reserve_main_serial_operation": reserve_mode_transport,
            "SerialActivityRejected": SerialActivityRejected,
            "requestPos": request_position,
            "offline_button": Widget(),
            "almStatusLab": Widget(),
            "almStatusLab2": Widget(),
            "setStepMonitorsVR": lambda: None,
            "logger": SimpleNamespace(warning=lambda *args: None),
        }
        namespace["_mode_change_is_blocked"] = self.compile_function(
            "_mode_change_is_blocked",
            namespace,
        )
        namespace["_set_offline_mode_status"] = self.compile_function(
            "_set_offline_mode_status",
            namespace,
        )
        toggle = self.compile_function("toggle_offline_mode", namespace)

        self.assertTrue(toggle())
        self.assertFalse(runtime["offlineMode"])
        self.assertEqual(attempts, [(False, False)])
        self.assertFalse(serial_lock.locked())
        self.assertFalse(registry.active)

    def test_mode_transition_acquires_logical_owner_before_transport(self):
        order = []
        lease = object()

        def acquire(name):
            self.assertEqual(name, "Mode transition")
            order.append("logical-acquire")
            return lease

        @contextmanager
        def reserve_transport():
            order.append("transport-enter")
            try:
                yield
            finally:
                order.append("transport-exit")

        class Widget:
            def config(self, **kwargs):
                pass

        namespace = {
            "RUN": {"offlineMode": True, "VR_angles": [9.0] * 6},
            "CAL": {f"J{axis}AngCur": str(axis) for axis in range(1, 7)},
            "_acquire_motion_request": acquire,
            "_finish_motion_request": (
                lambda value: order.append("logical-release") or True
            ),
            "_reserve_main_serial_operation": reserve_transport,
            "_mode_change_is_blocked": lambda *args, **kwargs: False,
            "requestPos": lambda: order.append("request-position") or False,
            "_set_offline_mode_status": lambda offline: None,
            "SerialActivityRejected": SerialActivityRejected,
            "logger": SimpleNamespace(warning=lambda *args: None),
            "almStatusLab": Widget(),
            "almStatusLab2": Widget(),
        }
        toggle = self.compile_function("toggle_offline_mode", namespace)

        self.assertFalse(toggle())
        self.assertEqual(
            order,
            [
                "logical-acquire",
                "transport-enter",
                "request-position",
                "transport-exit",
                "logical-release",
            ],
        )

    def test_offline_controller_correction_remains_queued(self):
        correction_requested = threading.Event()
        correction_requested.set()
        correction_namespace = {
            "controller_correction_requested": correction_requested,
            "controller_correction_state_lock": threading.Lock(),
            "application_closing": threading.Event(),
            "RUN": {"offlineMode": True},
            "serial_lock": threading.Lock(),
        }
        dispatch_correction = self.compile_function(
            "_try_dispatch_controller_correction",
            correction_namespace,
        )

        self.assertFalse(dispatch_correction())
        self.assertTrue(correction_requested.is_set())

    def test_joint_jog_handlers_are_unique_thin_wrappers(self):
        function_counts = {}
        for node in self.tree.body:
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                function_counts[node.name] = function_counts.get(node.name, 0) + 1

        for axis in range(1, 10):
            for direction in ("Neg", "Pos"):
                name = f"J{axis}jog{direction}"
                self.assertEqual(function_counts.get(name), 1, name)
                function = self.module_functions[name]
                calls = [node for node in ast.walk(function) if isinstance(node, ast.Call)]
                self.assertEqual(len(calls), 1, name)
                self.assertIsInstance(calls[0].func, ast.Name, name)
                self.assertEqual(calls[0].func.id, "_queue_joint_jog", name)

    def test_joint_sliders_submit_absolute_targets(self):
        for axis in range(9):
            name = f"J{axis + 1}sliderExecute"
            function = self.module_functions[name]
            calls = [node for node in ast.walk(function) if isinstance(node, ast.Call)]
            target_calls = [
                node
                for node in calls
                if isinstance(node.func, ast.Name)
                and node.func.id == "_queue_joint_target"
            ]
            self.assertEqual(len(target_calls), 1, name)
            self.assertIsInstance(target_calls[0].args[0], ast.Constant, name)
            self.assertEqual(target_calls[0].args[0].value, axis, name)

    def test_motion_controls_use_coordinate_space_tabs_and_vertical_rows(self):
        notebook_add_calls = [
            node
            for node in self.tree.body
            if isinstance(node, ast.Expr)
            and isinstance(node.value, ast.Call)
            and isinstance(node.value.func, ast.Attribute)
            and isinstance(node.value.func.value, ast.Name)
            and node.value.func.value.id == "motionControlNotebook"
            and node.value.func.attr == "add"
        ]
        self.assertEqual(len(notebook_add_calls), 3)
        self.assertEqual(
            [
                (
                    call.value.args[0].id,
                    next(
                        ast.literal_eval(keyword.value)
                        for keyword in call.value.keywords
                        if keyword.arg == "text"
                    ).strip(),
                )
                for call in notebook_add_calls
            ],
            [
                ("jointFrame", "Joint"),
                ("CartjogFrame", "Cartesian"),
                ("TooljogFrame", "Tool Frame"),
            ],
        )

        joint_rows = []
        cartesian_rows = []
        tool_rows = []
        for node in self.tree.body:
            if not isinstance(node, ast.Assign) or not isinstance(node.value, ast.Call):
                continue
            call = node.value
            if isinstance(call.func, ast.Name) and call.func.id == "create_joint_jog_frame":
                joint_rows.append(
                    (
                        ast.literal_eval(call.args[1]),
                        ast.literal_eval(call.args[2]),
                        ast.literal_eval(call.args[3]),
                    )
                )
            elif isinstance(call.func, ast.Name) and call.func.id == "create_cart_control":
                cartesian_rows.append(
                    (
                        ast.literal_eval(call.args[1]),
                        ast.literal_eval(call.args[2]),
                    )
                )
            elif isinstance(call.func, ast.Name) and call.func.id == "create_tool_control":
                tool_rows.append(
                    (
                        ast.literal_eval(call.args[1]),
                        ast.literal_eval(call.args[2]),
                    )
                )

        self.assertEqual(
            joint_rows,
            [(axis - 1, 0, f"J{axis}") for axis in range(1, 7)],
        )
        self.assertEqual(
            cartesian_rows,
            list(enumerate(("X", "Y", "Z", "Rz", "Ry", "Rx"))),
        )
        self.assertEqual(
            tool_rows,
            list(enumerate(("Tx", "Ty", "Tz", "Trz", "Try", "Trx"))),
        )
        for function_name in ("create_cart_control", "create_tool_control"):
            scale_calls = [
                node
                for node in ast.walk(self.module_functions[function_name])
                if isinstance(node, ast.Call)
                and isinstance(node.func, ast.Name)
                and node.func.id == "Scale"
            ]
            self.assertEqual(scale_calls, [], function_name)

    def test_named_position_buttons_route_through_atomic_joint_submission(self):
        button_commands = {}
        for name in ("startPositionBut", "shutdownPositionBut"):
            constructor = self.module_assignments[name].value
            self.assertIsInstance(constructor, ast.Call)
            button_commands[name] = next(
                keyword.value.id
                for keyword in constructor.keywords
                if keyword.arg == "command"
            )
        self.assertEqual(
            button_commands,
            {
                "startPositionBut": "MoveToStartPosition",
                "shutdownPositionBut": "MoveToShutdownPosition",
            },
        )

        queue_function = self.module_functions["_queue_primary_joint_position"]
        submit_calls = [
            node
            for node in ast.walk(queue_function)
            if isinstance(node, ast.Call)
            and isinstance(node.func, ast.Attribute)
            and node.func.attr in ("submit_target", "submit_targets")
        ]
        self.assertEqual(len(submit_calls), 1)
        self.assertEqual(submit_calls[0].func.attr, "submit_targets")

    def test_home_reference_binding_query_and_invalidation_contracts(self):
        base_identity = parse_controller_identity_response(
            VALID_CONTROLLER_IDENTITY_RESPONSE
        )
        capability_identity = ControllerIdentity(
            controller_hardware_id=base_identity.controller_hardware_id,
            driver_model=base_identity.driver_model,
            firmware_version="6.7.1-ar4hmi.5",
            robot_model=base_identity.robot_model,
            robot_version=base_identity.robot_version,
            serial_number=base_identity.serial_number,
            asset_tag=base_identity.asset_tag,
            protocol_capabilities=(
                base_identity.protocol_capabilities
                + (
                    CONTROLLER_CAPABILITY_HOME_REFERENCE_V1,
                    CONTROLLER_CAPABILITY_HOME_REFERENCE_V2,
                )
            ),
        )
        port = SimpleNamespace(is_open=True)
        invalidation_warnings = []
        namespace = {
            "dataclass": dataclass,
            "Optional": Optional,
            "ControllerIdentity": ControllerIdentity,
            "PrimaryHomeReference": PrimaryHomeReference,
            "MotionInputError": MotionInputError,
            "validate_controller_hardware_id": validate_controller_hardware_id,
            "CONTROLLER_CAPABILITY_HOME_REFERENCE_V1": (
                CONTROLLER_CAPABILITY_HOME_REFERENCE_V1
            ),
            "RUN": {"ser": port},
            "gcode_storage_state_lock": threading.Lock(),
            "main_controller_identity_binding": None,
            "gcode_storage_media_binding": None,
            "logger": SimpleNamespace(
                warning=lambda *values: invalidation_warnings.append(values)
            ),
        }
        binding_type = self.compile_class(
            "MainControllerIdentityBinding",
            namespace,
        )
        valid_reference = PrimaryHomeReference(
            (True, True, True),
            (163.8, -38.2, -88.9),
        )

        with self.assertRaisesRegex(
            MotionInputError,
            "home-reference capability is inconsistent",
        ):
            binding_type(port, capability_identity)
        with self.assertRaisesRegex(
            MotionInputError,
            "home-reference capability is inconsistent",
        ):
            binding_type(port, base_identity, valid_reference)

        namespace["main_controller_identity_binding"] = binding_type(
            port,
            capability_identity,
            valid_reference,
        )
        namespace["_current_main_controller_identity"] = self.compile_function(
            "_current_main_controller_identity",
            namespace,
        )
        namespace["_bind_main_controller_home_reference"] = (
            self.compile_function(
                "_bind_main_controller_home_reference",
                namespace,
            )
        )
        namespace["_current_primary_home_reference"] = self.compile_function(
            "_current_primary_home_reference",
            namespace,
        )
        namespace["_invalidate_bound_primary_home_reference"] = (
            self.compile_function(
                "_invalidate_bound_primary_home_reference",
                namespace,
            )
        )

        self.assertEqual(
            namespace["_current_primary_home_reference"](port),
            valid_reference,
        )
        self.assertTrue(
            namespace["_invalidate_bound_primary_home_reference"](port)
        )
        self.assertEqual(
            namespace["_current_primary_home_reference"](port),
            PrimaryHomeReference((False, False, False), (0.0, 0.0, 0.0)),
        )

        responses = ["A1B163800C1D-38200E1F-88900"]

        def exchange(
            command,
            *,
            response_timeout,
            expected_serial_port,
        ):
            self.assertEqual(command, "H2\n")
            self.assertEqual(response_timeout, 1.0)
            self.assertIs(expected_serial_port, port)
            return responses.pop(0)

        namespace.update({
            "_exchange_legacy_main_command": exchange,
            "SERIAL_STARTUP_READ_TIMEOUT_SECONDS": 1.0,
            "parse_primary_home_reference_response": (
                parse_primary_home_reference_response
            ),
            "ProtocolResponseError": ProtocolResponseError,
        })
        namespace["_query_primary_home_reference"] = self.compile_function(
            "_query_primary_home_reference",
            namespace,
        )

        queried_reference = namespace["_query_primary_home_reference"](port)
        self.assertEqual(queried_reference, valid_reference)

        responses.append("invalid")
        with self.assertRaisesRegex(
            ProtocolResponseError,
            "home-reference response is invalid",
        ):
            namespace["_query_primary_home_reference"](port)

        invalidations = []
        namespace.update({
            "_invalidate_uncertain_controller_calibration": (
                lambda reason: invalidations.append(reason) or False
            ),
        })
        namespace["_apply_calibration_home_reference"] = self.compile_function(
            "_apply_calibration_home_reference",
            namespace,
        )
        self.assertTrue(
            namespace["_apply_calibration_home_reference"](
                port,
                valid_reference,
                None,
            )
        )
        self.assertEqual(
            namespace["_current_primary_home_reference"](port),
            valid_reference,
        )
        self.assertFalse(
            namespace["_apply_calibration_home_reference"](
                port,
                None,
                "query failed",
            )
        )
        self.assertEqual(
            namespace["_current_primary_home_reference"](port),
            PrimaryHomeReference((False, False, False), (0.0, 0.0, 0.0)),
        )
        self.assertEqual(
            invalidations,
            [
                "calibration home-reference synchronization failed: "
                "query failed"
            ],
        )
        port.is_open = False
        self.assertFalse(
            namespace["_invalidate_bound_primary_home_reference"](port)
        )
        self.assertEqual(len(invalidation_warnings), 1)
        self.assertEqual(
            invalidation_warnings[0][1],
            "the controller connection is closed",
        )

    def test_named_position_references_match_program_and_controller_contract(self):
        home_program = HOME_PROGRAM_SOURCE.read_text(encoding="utf-8")
        home_match = re.search(
            r"J1\s+([-0-9.]+)\s+J2\s+([-0-9.]+)\s+"
            r"J3\s+([-0-9.]+)\s+J4\s+([-0-9.]+)\s+"
            r"J5\s+([-0-9.]+)\s+J6\s+([-0-9.]+)",
            home_program,
        )
        self.assertIsNotNone(home_match)
        self.assertEqual(
            tuple(float(value) for value in home_match.groups()),
            PRIMARY_START_POSITION,
        )

        firmware_source = TEENSY_SOURCE.read_text(encoding="utf-8")
        home_reference_contract = (
            TEENSY_HOME_REFERENCE_CONTRACT.read_text(encoding="utf-8")
        )
        self.assertRegex(
            home_reference_contract,
            r"constexpr\s+size_t\s+kPrimaryHomeReferenceAxisCount\s*=\s*3\s*;",
        )
        self.assertIn(
            'const char *HOME_REFERENCE_V1_CAPABILITY = "HOME_REFERENCE_V1";',
            firmware_source,
        )
        self.assertIn(
            'const char *HOME_REFERENCE_V2_CAPABILITY = "HOME_REFERENCE_V2";',
            firmware_source,
        )
        capabilities_start = firmware_source.index(
            "const char *const PROTOCOL_CAPABILITIES[]"
        )
        capabilities_end = firmware_source.index("};", capabilities_start)
        advertised_capabilities = firmware_source[
            capabilities_start:capabilities_end
        ]
        self.assertIn(
            "HOME_REFERENCE_V1_CAPABILITY",
            advertised_capabilities,
        )
        self.assertIn(
            "HOME_REFERENCE_V2_CAPABILITY",
            advertised_capabilities,
        )

        v1_handler_start = firmware_source.index(
            "void handle_home_reference_v1_command()"
        )
        v2_handler_start = firmware_source.index(
            "void handle_home_reference_v2_command()",
            v1_handler_start,
        )
        next_handler_start = firmware_source.index(
            "void handle_set_robot_id_command(",
            v2_handler_start,
        )
        v1_handler = firmware_source[
            v1_handler_start:v2_handler_start
        ]
        v2_handler = firmware_source[
            v2_handler_start:next_handler_start
        ]
        self.assertIn(
            "build_primary_home_reference_v1_response(",
            v1_handler,
        )
        self.assertNotIn(
            "build_primary_home_reference_v2_response(",
            v1_handler,
        )
        self.assertIn(
            "build_primary_home_reference_v2_response(",
            v2_handler,
        )
        self.assertNotIn(
            "build_primary_home_reference_v1_response(",
            v2_handler,
        )
        self.assertIn(
            "build_primary_home_reference_v1_response(",
            home_reference_contract,
        )
        self.assertIn(
            "build_primary_home_reference_v2_response(",
            home_reference_contract,
        )

        dispatch_start = firmware_source.index(
            'if (function == "HR")'
        )
        dispatch_end = firmware_source.index(
            'if (function == "RB")',
            dispatch_start,
        )
        home_reference_dispatch = firmware_source[
            dispatch_start:dispatch_end
        ]
        self.assertRegex(
            home_reference_dispatch,
            (
                r'if\s*\(\s*function\s*==\s*"HR"\s*\)\s*\{\s*'
                r"handle_home_reference_v1_command\(\);\s*\}"
            ),
        )
        self.assertRegex(
            home_reference_dispatch,
            (
                r'if\s*\(\s*function\s*==\s*"H2"\s*\)\s*\{\s*'
                r"handle_home_reference_v2_command\(\);\s*\}"
            ),
        )
        shutdown_function = self.module_functions[
            "MoveToShutdownPosition"
        ]
        referenced_names = {
            node.id
            for node in ast.walk(shutdown_function)
            if isinstance(node, ast.Name)
        }
        self.assertIn("_current_primary_home_reference", referenced_names)
        self.assertNotIn("CAL", referenced_names)

        calibration_start = firmware_source.index(
            'if (function == "LL")'
        )
        calibration_end = firmware_source.index(
            '//----- LIVE CARTESIAN JOG',
            calibration_start,
        )
        calibration_handler = firmware_source[
            calibration_start:calibration_end
        ]
        limit_search_start = firmware_source.index(
            "bool driveLimit("
        )
        limit_search_end = firmware_source.index(
            "\nbool backOff(",
            limit_search_start,
        )
        limit_search = firmware_source[
            limit_search_start:limit_search_end
        ]
        self.assertIn("!isfinite(SpeedVal)", limit_search)
        self.assertIn("!isfinite(minSpeedDelay)", limit_search)
        self.assertIn("if (calcStepGap <= 0) return false;", limit_search)
        self.assertIn("limitConfirmed[i] = 1;", limit_search)
        self.assertIn("&& limitSeen[i] == 0", limit_search)
        self.assertIn(
            "if (requested[i] == 1 && limitConfirmed[i] == 0) return false;",
            limit_search,
        )
        guarded_limit_searches = [
            match.start()
            for match in re.finditer(
                r"if \(!driveLimit\(JStep, Jreq, SpeedIn\)\)",
                calibration_handler,
            )
        ]
        self.assertEqual(len(guarded_limit_searches), 2)
        self.assertNotIn(
            'if (!estopActive) Serial.println("ER");',
            calibration_handler,
        )
        self.assertEqual(
            calibration_handler.count(
                "finish_calibration_failure_response();"
            ),
            5,
        )
        self.assertRegex(
            firmware_source,
            (
                r"void\s+finish_calibration_failure_response\(\)\s*\{\s*"
                r'Serial\.println\("ER"\);\s*'
                r"consume_current_command\(\);\s*\}"
            ),
        )
        self.assertRegex(
            calibration_handler,
            (
                r"int32_t\s+stagedPrimaryHomeReference\s*\[\s*"
                r"ar4_protocol::kPrimaryHomeReferenceAxisCount\s*\]"
                r"\s*=\s*\{\s*\};"
            ),
        )
        fail_closed_calibration_body = (
            r"\s*\{\s*Serial\.println\(\"ER\"\);\s*"
            r"consume_current_command\(\);\s*return;\s*\}"
        )
        self.assertRegex(
            calibration_handler,
            (
                r"if\s*\(\s*"
                r"!ar4_protocol::field_boundaries_cover_command\s*\(\s*"
                r"inData\.length\(\)\s*,\s*positions\s*\)\s*"
                r"\|\|\s*!parse_int_marker_fields\s*\(\s*"
                r"inData\s*,\s*positions\s*,\s*requested\s*\)\s*"
                r"\|\|\s*!ar4_protocol::values_are_binary\s*\(\s*"
                r"requested\s*\)\s*"
                r"\|\|\s*!parse_float_marker_fields\s*\(\s*"
                r"inData\s*,\s*positions\s*\+\s*9\s*,\s*"
                r"calibrationOffsets\s*\)\s*\)"
            )
            + fail_closed_calibration_body,
        )
        self.assertRegex(
            calibration_handler,
            r"if\s*\(\s*!hasRequestedAxis\s*\)"
            + fail_closed_calibration_body,
        )
        for staged_steps in (
            "stagedMasterSteps",
            "stagedCenterSteps",
            "stagedJointFiveSteps",
        ):
            self.assertRegex(
                calibration_handler,
                rf"int\s+{staged_steps}\s*\[\s*9\s*\]\s*=\s*\{{\s*\}};",
            )
        calibration_reference_loop = (
            r"for\s*\(\s*int\s+axis\s*=\s*0\s*;\s*"
            r"axis\s*<\s*9\s*;\s*\+\+axis\s*\)\s*\{\s*"
        )
        self.assertRegex(
            calibration_handler,
            calibration_reference_loop
            + (
                r"if\s*\(\s*!ar4_protocol::calibration_reference_steps"
                r"\s*\(\s*Jreq\[axis\]\s*,\s*"
                r"calibrationDirections\[axis\]\s*,\s*"
                r"positiveLimits\[axis\]\s*,\s*"
                r"negativeLimits\[axis\]\s*,\s*"
                r"stepsPerUnit\[axis\]\s*,\s*"
                r"JStepLim\[axis\]\s*,\s*"
                r"baseOffsets\[axis\]\s*,\s*"
                r"calibrationOffsets\[axis\]\s*,\s*"
                r"axis\s*==\s*4\s*,\s*"
                r"stagedMasterSteps\[axis\]\s*,\s*"
                r"stagedCenterSteps\[axis\]\s*,\s*"
                r"stagedJointFiveSteps\[axis\]\s*\)\s*\)"
            )
            + fail_closed_calibration_body,
        )
        self.assertRegex(
            calibration_handler,
            (
                r"if\s*\(\s*static_cast<size_t>\(axis\)\s*<\s*"
                r"ar4_protocol::kPrimaryHomeReferenceAxisCount\s*"
                r"&&\s*Jreq\[axis\]\s*==\s*1\s*"
                r"&&\s*!ar4_protocol::"
                r"primary_home_reference_millidegrees\s*\(\s*"
                r"\(\s*static_cast<float>"
                r"\(stagedMasterSteps\[axis\]\)\s*-\s*"
                r"static_cast<float>\(zeroSteps\[axis\]\)\s*\)"
                r"\s*/\s*stepsPerUnit\[axis\]\s*,\s*"
                r"stagedPrimaryHomeReference\[axis\]\s*\)\s*\)"
            )
            + fail_closed_calibration_body,
        )
        primary_reference_loop = (
            r"for\s*\(\s*size_t\s+axis\s*=\s*0\s*;\s*"
            r"axis\s*<\s*"
            r"ar4_protocol::kPrimaryHomeReferenceAxisCount\s*;\s*"
            r"\+\+axis\s*\)\s*\{\s*"
            r"if\s*\(\s*Jreq\[axis\]\s*==\s*1\s*\)\s*\{\s*"
        )
        self.assertRegex(
            calibration_handler,
            primary_reference_loop
            + (
                r"ar4_protocol::invalidate_primary_home_reference_axis"
                r"\s*\(\s*invalidatedHomeReference\s*,\s*axis\s*\)"
                r"\s*;\s*\}\s*\}\s*"
                r"primaryHomeReference\s*=\s*invalidatedHomeReference\s*;"
            ),
        )
        self.assertRegex(
            calibration_handler,
            primary_reference_loop
            + (
                r"ar4_protocol::set_primary_home_reference\s*\(\s*"
                r"committedHomeReference\s*,\s*axis\s*,\s*"
                r"stagedPrimaryHomeReference\[axis\]\s*\)"
                r"\s*;\s*\}\s*\}\s*"
                r"primaryHomeReference\s*=\s*committedHomeReference\s*;"
            ),
        )
        reference_invalidation_helper = calibration_handler.index(
            "invalidate_primary_home_reference_axis"
        )
        reference_invalidation = calibration_handler.index(
            "primaryHomeReference = invalidatedHomeReference;"
        )
        backoff = calibration_handler.index("if (!backOff(")
        step_monitor_commit = calibration_handler.index(
            "int *stepMonitors[9]"
        )
        parse_validation = calibration_handler.index(
            "!ar4_protocol::field_boundaries_cover_command"
        )
        calibration_reference_validation = calibration_handler.index(
            "!ar4_protocol::calibration_reference_steps"
        )
        home_reference_validation = calibration_handler.index(
            "!ar4_protocol::primary_home_reference_millidegrees"
        )
        self.assertLess(parse_validation, guarded_limit_searches[0])
        self.assertLess(
            calibration_reference_validation,
            guarded_limit_searches[0],
        )
        self.assertLess(
            home_reference_validation,
            guarded_limit_searches[0],
        )
        self.assertLess(
            reference_invalidation_helper,
            reference_invalidation,
        )
        self.assertLess(reference_invalidation, guarded_limit_searches[0])
        self.assertLess(guarded_limit_searches[0], backoff)
        self.assertLess(backoff, guarded_limit_searches[1])
        self.assertLess(guarded_limit_searches[1], step_monitor_commit)
        backoff_start = firmware_source.index(
            "bool backOff("
        )
        backoff_end = firmware_source.index(
            "//CHECK ENCODERS",
            backoff_start,
        )
        backoff_source = firmware_source[backoff_start:backoff_end]
        self.assertIn(
            "ar4_protocol::calibration_release_step_limit(",
            backoff_source,
        )
        self.assertIn(
            "digitalRead(calPins[axis]) == LOW",
            backoff_source,
        )
        self.assertIn(
            ">= CALIBRATION_RELEASE_STABLE_MICROSECONDS",
            backoff_source,
        )
        self.assertIn(
            "completedSteps[axis] >= maximumSteps[axis]",
            backoff_source,
        )
        self.assertIn(
            "configuredStepLimits[axis]",
            backoff_source,
        )
        empty_selection_guard = calibration_handler.index(
            "if (!hasRequestedAxis)"
        )
        self.assertLess(empty_selection_guard, guarded_limit_searches[0])
        final_drive = calibration_handler.index("if (!driveMotorsJ")
        post_drive_estop_guard = calibration_handler.index(
            "if (estopActive) {",
            final_drive,
        )
        reference_commit_helper = calibration_handler.index(
            "set_primary_home_reference"
        )
        reference_commit = calibration_handler.index(
            "primaryHomeReference = committedHomeReference;"
        )
        terminal_response = calibration_handler.index(
            "sendRobotPos();",
            reference_commit,
        )
        self.assertLess(final_drive, post_drive_estop_guard)
        self.assertLess(post_drive_estop_guard, reference_commit_helper)
        self.assertLess(reference_commit_helper, reference_commit)
        self.assertLess(reference_commit, terminal_response)

        invalidation_terminals = {
            "UP": "if (!robot_set_AR())",
            "SP": 'Serial.println("Done");',
        }
        for command, terminal_marker in invalidation_terminals.items():
            handler_start = firmware_source.index(
                f'if (function == "{command}")'
            )
            next_handler = firmware_source.index(
                "//-----COMMAND",
                handler_start + 1,
            )
            handler = firmware_source[handler_start:next_handler]
            self.assertRegex(
                handler,
                (
                    r"ar4_protocol::invalidate_primary_home_reference"
                    r"\s*\(\s*invalidatedHomeReference\s*\)\s*;"
                ),
            )
            invalidation = handler.index(
                "ar4_protocol::invalidate_primary_home_reference("
            )
            write_back = handler.index(
                "primaryHomeReference = invalidatedHomeReference;"
            )
            self.assertLess(
                invalidation,
                write_back,
            )
            self.assertLess(write_back, handler.index(terminal_marker))

    def test_named_position_online_route_preserves_external_axes(self):
        actual = (10.0, 20.0, 30.0, 40.0, 50.0, 60.0, 7.0, 8.0, 9.0)
        profile = object()
        validation_calls = []
        submissions = []
        virtual_targets = []

        class Calibration:
            def validate_positions(self, positions):
                positions = tuple(positions)
                validation_calls.append(positions)
                return positions

        class Dispatcher:
            active = False

            def submit_targets(self, targets, positions, move_profile):
                targets = tuple(targets)
                positions = tuple(positions)
                submissions.append((targets, positions, move_profile))
                resolved = tuple(
                    position if target is None else float(target)
                    for position, target in zip(positions, targets)
                )
                return SimpleNamespace(target=resolved, coalesced=False)

        class Label:
            def config(self, **kwargs):
                pass

        namespace = {
            "RUN": {"xboxUse": 1, "offlineMode": False},
            "application_closing": threading.Event(),
            "controller_correction_requested": threading.Event(),
            "finite_number": finite_number,
            "MotionInputError": MotionInputError,
            "MotionQueueFault": MotionQueueFault,
            "MotionTransportBusy": MotionTransportBusy,
            "_current_joint_positions": lambda: actual,
            "_current_controller_joint_calibration": Calibration,
            "_current_joint_motion_profile": lambda: profile,
            "deferred_joint_adjustments": SimpleNamespace(pending=False),
            "motion_request_registry": SimpleNamespace(active=False),
            "joint_motion_dispatcher": Dispatcher(),
            "_reserve_joint_motion_request": lambda: (object(), True),
            "_abandon_joint_motion_request": lambda lease: True,
            "legacy_serial_result_pending": threading.Event(),
            "live_serial_result_pending": threading.Event(),
            "serial_lock": SimpleNamespace(locked=lambda: False),
            "_try_set_virtual_joint_target": virtual_targets.append,
            "_set_joint_motion_target_display": lambda target: True,
            "build_virtual_joint_command": lambda positions, move_profile: "",
            "_start_offline_joint_motion": lambda command: True,
            "confirmed_position_generation": 3,
            "almStatusLab": Label(),
            "almStatusLab2": Label(),
            "logger": SimpleNamespace(error=lambda message: None),
        }
        route = self.compile_function(
            "_queue_primary_joint_position",
            namespace,
        )

        self.assertTrue(route(PRIMARY_START_POSITION))
        expected_updates = PRIMARY_START_POSITION + (None, None, None)
        self.assertEqual(
            validation_calls,
            [PRIMARY_START_POSITION + actual[6:]],
        )
        self.assertEqual(
            submissions,
            [(expected_updates, actual, profile)],
        )
        self.assertEqual(
            virtual_targets,
            [PRIMARY_START_POSITION + actual[6:]],
        )

