    def test_primary_joint_pose_keys_match_widget_group_order(self):
        primary_count_assignment = next(
            node
            for node in self.tree.body
            if isinstance(node, ast.Assign)
            and any(
                isinstance(target, ast.Name)
                and target.id == "PRIMARY_JOINT_COUNT"
                for target in node.targets
            )
        )
        position_keys_assignment = next(
            node
            for node in self.tree.body
            if isinstance(node, ast.Assign)
            and any(
                isinstance(target, ast.Name)
                and target.id == "CALIBRATION_POSITION_KEYS"
                for target in node.targets
            )
        )
        primary_joint_count = ast.literal_eval(primary_count_assignment.value)
        position_keys = ast.literal_eval(position_keys_assignment.value)
        widget_groups = self.module_functions["_calibration_pose_widget_groups"]
        return_node = next(
            node
            for node in widget_groups.body
            if isinstance(node, ast.Return)
        )
        entry_names = tuple(
            entry.id
            for entry in return_node.value.elts[0].elts
        )

        self.assertEqual(primary_joint_count, 6)
        self.assertEqual(len(position_keys), len(entry_names))
        self.assertEqual(
            position_keys[:primary_joint_count],
            tuple(f"J{axis}AngCur" for axis in range(1, 7)),
        )
        self.assertEqual(
            entry_names[:primary_joint_count],
            tuple(
                f"J{axis}curAngEntryField"
                for axis in range(1, 7)
            ),
        )

    def test_primary_joint_entry_bindings_submit_and_preserve_edits(self):
        class Entry:
            def __init__(self, value):
                self.value = value
                self.bindings = {}
                self.selections = []

            def bind(self, sequence, callback):
                self.bindings[sequence] = callback

            def get(self):
                return self.value

            def selection_range(self, start, end):
                self.selections.append((start, end))

            def delete(self, *args):
                self.value = ""

            def insert(self, index, value):
                self.value = value

        accepted = {"value": True}
        submissions = []

        def queue_target(axis, value):
            submissions.append((axis, value))
            return accepted["value"]

        namespace = {
            "CAL": {"J3AngCur": "12.5"},
            "_queue_joint_target": queue_target,
        }
        bind_target = self.compile_function(
            "_bind_joint_target_entry",
            namespace,
        )
        write_position = self.compile_function(
            "_write_joint_position_entry",
            namespace,
        )
        entry = Entry("3.0")

        bind_target(2, entry)

        self.assertEqual(
            set(entry.bindings),
            {
                "<FocusIn>",
                "<Button-1>",
                "<KeyPress>",
                "<Return>",
                "<KP_Enter>",
                "<Escape>",
                "<FocusOut>",
            },
        )
        keyboard_entry = Entry("8.0")
        bind_target(2, keyboard_entry)
        keyboard_entry.bindings["<FocusIn>"](SimpleNamespace())
        self.assertTrue(keyboard_entry._joint_target_editing)
        self.assertTrue(keyboard_entry._joint_target_replace_on_key)
        self.assertEqual(keyboard_entry.selections, [(0, "end")])
        keyboard_entry.bindings["<Button-1>"](SimpleNamespace())
        self.assertTrue(keyboard_entry._joint_target_pointer_focus)
        self.assertTrue(keyboard_entry._joint_target_editing)
        self.assertFalse(keyboard_entry._joint_target_replace_on_key)
        keyboard_entry.bindings["<KeyPress>"](
            SimpleNamespace(keysym="BackSpace")
        )
        self.assertFalse(keyboard_entry._joint_target_pointer_focus)
        self.assertFalse(keyboard_entry._joint_target_replace_on_key)

        entry.bindings["<Button-1>"](SimpleNamespace())
        entry.bindings["<FocusIn>"](SimpleNamespace())
        self.assertFalse(entry._joint_target_pointer_focus)
        self.assertFalse(entry._joint_target_replace_on_key)
        self.assertEqual(entry.selections, [])
        entry.bindings["<KeyPress>"](SimpleNamespace(keysym="BackSpace"))
        self.assertEqual(entry.selections, [])
        entry.value = "-4.25"
        self.assertTrue(entry._joint_target_editing)
        self.assertFalse(write_position(entry, "8.0"))
        self.assertEqual(entry.value, "-4.25")

        self.assertEqual(
            entry.bindings["<Return>"](SimpleNamespace()),
            "break",
        )
        self.assertEqual(submissions, [(2, "-4.25")])
        self.assertFalse(entry._joint_target_editing)
        self.assertTrue(entry._joint_target_replace_on_key)
        self.assertTrue(write_position(entry, "8.0"))
        self.assertEqual(entry.value, "8.0")

        entry.bindings["<KeyPress>"](SimpleNamespace(keysym="Shift_L"))
        self.assertFalse(entry._joint_target_editing)
        self.assertTrue(entry._joint_target_replace_on_key)
        self.assertEqual(entry.selections, [(0, "end")])

        entry.bindings["<KeyPress>"](SimpleNamespace(keysym="1"))
        entry.value = "1"
        self.assertTrue(entry._joint_target_editing)
        self.assertFalse(entry._joint_target_replace_on_key)
        self.assertEqual(entry.selections, [(0, "end"), (0, "end")])
        self.assertFalse(write_position(entry, "9.0"))
        self.assertEqual(entry.value, "1")

        entry.bindings["<FocusOut>"](SimpleNamespace())
        self.assertEqual(entry.value, "12.5")
        self.assertFalse(entry._joint_target_editing)

        accepted["value"] = False
        entry.bindings["<FocusIn>"](SimpleNamespace())
        self.assertTrue(entry._joint_target_replace_on_key)
        self.assertEqual(
            entry.selections,
            [(0, "end"), (0, "end"), (0, "end")],
        )
        entry.value = "invalid"
        self.assertEqual(
            entry.bindings["<KP_Enter>"](SimpleNamespace()),
            "break",
        )
        self.assertEqual(submissions[-1], (2, "invalid"))
        self.assertTrue(entry._joint_target_editing)
        self.assertFalse(write_position(entry, "10.0"))
        self.assertEqual(entry.value, "invalid")

        self.assertEqual(
            entry.bindings["<Escape>"](SimpleNamespace()),
            "break",
        )
        self.assertEqual(entry.value, "12.5")
        self.assertFalse(entry._joint_target_editing)

        with self.assertRaisesRegex(ValueError, r"\[0, 5\]"):
            bind_target(6, Entry("0"))

    def test_joint_motion_host_routing_uses_semantic_target(self):
        class Label:
            def __init__(self):
                self.events = []

            def config(self, **kwargs):
                self.events.append(kwargs)

        class Logger:
            def __init__(self):
                self.errors = []

            def error(self, message):
                self.errors.append(message)

        class Dispatcher:
            def __init__(self):
                self.calls = []

            def submit_target(self, axis, target, actual, profile):
                self.calls.append(("target", axis, target, actual, profile))
                values = list(actual)
                values[axis] = target
                return SimpleNamespace(target=tuple(values), coalesced=True)

            def submit_delta(self, axis, delta, actual, profile):
                self.calls.append(("delta", axis, delta, actual, profile))
                values = list(actual)
                values[axis] += delta
                return SimpleNamespace(target=tuple(values), coalesced=False)

        class Deferred:
            pending = False

        actual = (0.0,) * 9
        profile = object()
        dispatcher = Dispatcher()
        virtual_targets = []
        first_label = Label()
        second_label = Label()
        logger = Logger()
        namespace = {
            "RUN": {"xboxUse": 1, "offlineMode": False, "VR_angles": [0.0] * 6},
            "application_closing": SimpleNamespace(is_set=lambda: False),
            "controller_correction_requested": threading.Event(),
            "math": math,
            "finite_number": finite_number,
            "MotionInputError": MotionInputError,
            "MotionQueueFault": MotionQueueFault,
            "MotionTransportBusy": MotionTransportBusy,
            "_current_joint_motion_profile": lambda: profile,
            "_current_joint_positions": lambda: actual,
            "deferred_joint_adjustments": Deferred(),
            "joint_motion_dispatcher": dispatcher,
            "_defer_joint_target": lambda *args: True,
            "_defer_joint_adjustment": lambda *args: True,
            "_try_set_virtual_joint_target": virtual_targets.append,
            "build_virtual_joint_command": lambda positions, move_profile: "virtual",
            "rj_command": lambda command: None,
            "almStatusLab": first_label,
            "almStatusLab2": second_label,
            "logger": logger,
        }
        route = self.compile_function("_queue_joint_motion", namespace)

        accepted = route(0, 20, absolute=True)

        self.assertTrue(accepted)
        self.assertEqual(dispatcher.calls, [("target", 0, 20.0, actual, profile)])
        self.assertEqual(virtual_targets, [(20.0,) + (0.0,) * 8])
        self.assertEqual(logger.errors, [])

        self.assertFalse(route(0, True, absolute=True))
        self.assertEqual(dispatcher.calls, [("target", 0, 20.0, actual, profile)])
        self.assertIn("must be numeric", logger.errors[-1])

